import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"File formats","description":"","frontmatter":{},"headers":[],"relativePath":"reference/file-formats.md","filePath":"reference/file-formats.md","lastUpdated":1792715383000}'),i={name:"reference/file-formats.md"};function o(l,e,r,p,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="file-formats" tabindex="-1">File formats <a class="header-anchor" href="#file-formats" aria-label="Permalink to &quot;File formats&quot;">​</a></h1><p>This page describes the files practice mode can import, with examples. All files can be UTF-8 (with or without BOM), UTF-16 or a legacy encoding such as GBK; MeetCue detects the encoding. Windows and Unix line endings both work.</p><h2 id="subtitles-srt" tabindex="-1">Subtitles: SRT <a class="header-anchor" href="#subtitles-srt" aria-label="Permalink to &quot;Subtitles: SRT&quot;">​</a></h2><p>Standard SubRip files. Put the speaker&#39;s name at the start of the text, followed by a colon.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1</span></span>
<span class="line"><span>00:00:01,200 --&gt; 00:00:04,800</span></span>
<span class="line"><span>Interviewer: Could you start by introducing yourself?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>00:00:05,500 --&gt; 00:00:12,000</span></span>
<span class="line"><span>Alex: Sure. I&#39;ve worked on data center networks for eight years.</span></span></code></pre></div><p>Timestamps may use a comma or a dot before the milliseconds.</p><h2 id="subtitles-webvtt" tabindex="-1">Subtitles: WebVTT <a class="header-anchor" href="#subtitles-webvtt" aria-label="Permalink to &quot;Subtitles: WebVTT&quot;">​</a></h2><p>Speakers come from <code>&lt;v Name&gt;</code> voice tags or a <code>Name:</code> prefix. Hours can be left out.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WEBVTT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>00:01.200 --&gt; 00:04.800</span></span>
<span class="line"><span>&lt;v Interviewer&gt;Could you start by introducing yourself?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>00:05.500 --&gt; 00:12.000</span></span>
<span class="line"><span>&lt;v Alex&gt;Sure. I&#39;ve worked on data center networks for eight years.</span></span></code></pre></div><h2 id="subtitles-plain-text" tabindex="-1">Subtitles: plain text <a class="header-anchor" href="#subtitles-plain-text" aria-label="Permalink to &quot;Subtitles: plain text&quot;">​</a></h2><p>One sentence per line, optionally with a <code>Name:</code> prefix and an optional timestamp in brackets. Full-width colons (<code>：</code>) work too.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[00:01] Interviewer: Could you start by introducing yourself?</span></span>
<span class="line"><span>[00:05] Alex: Sure. I&#39;ve worked on data center networks for eight years.</span></span></code></pre></div><p>Without timestamps, MeetCue plays the lines one after another. Without speaker names, the model labels each line as a question or an answer, and you check the result.</p><h2 id="question-list-text-and-markdown" tabindex="-1">Question list: text and Markdown <a class="header-anchor" href="#question-list-text-and-markdown" aria-label="Permalink to &quot;Question list: text and Markdown&quot;">​</a></h2><p>One question per line. A line starting with <code>#</code> starts a group; the group name appears in the preview and the review. Empty lines are ignored, and Markdown list markers (<code>-</code>, <code>*</code>, <code>1.</code>) are removed.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Basics</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> What is the difference between the control plane and the data plane?</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> How does BGP choose a best path?</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Design</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> How would you design a network for two data centers?</span></span></code></pre></div><h2 id="question-list-csv" tabindex="-1">Question list: CSV <a class="header-anchor" href="#question-list-csv" aria-label="Permalink to &quot;Question list: CSV&quot;">​</a></h2><p>The first row names the columns. Only <code>question</code> is required.</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><code>question</code></td><td>The question</td></tr><tr><td><code>reference_answer</code></td><td>A model answer, used for feedback in the review</td></tr><tr><td><code>category</code></td><td>A group name</td></tr><tr><td><code>followups</code></td><td>Follow-up questions, separated by <code>|</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>question,reference_answer,category,followups</span></span>
<span class="line"><span>&quot;What is SDN?&quot;,&quot;Separates control and data planes; central controller; programmable through APIs.&quot;,Basics,&quot;Which controllers have you used?|What are the risks?&quot;</span></span></code></pre></div><h2 id="sample-files" tabindex="-1">Sample files <a class="header-anchor" href="#sample-files" aria-label="Permalink to &quot;Sample files&quot;">​</a></h2><ul><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/sdn-interview.srt" target="_blank" rel="noreferrer">sdn-interview.srt</a>: a short interview in Chinese and English.</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/questions-network.csv" target="_blank" rel="noreferrer">questions-network.csv</a>: ten network architecture questions with reference answers.</li></ul>`,22)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
